import numpy as np
import scipy.stats as st

def close(a, b, rtol: float = 1e-7) -> bool:
    x = np.asarray(a).astype(float).ravel()
    y = np.asarray(b).astype(float).ravel()
    if x.shape != y.shape:
        return False
    for i in range(x.shape[0]):
        u = float(x[i])
        v = float(y[i])
        if not (abs(u - v) <= 1e-10 + rtol * abs(v) or (u != u and v != v)):
            print('mismatch', i, u, v)
            return False
    return True

xs = [-3.0, -1.0, -0.2, 0.0, 0.4, 1.5, 4.0]

@test
def test_levy_a():
    assert close(st.levy_stable.pdf(xs, 1.6, 0.4), [0.032822124198630176, 0.24604973364197927, 0.28255985273866324, 0.27391239673192175, 0.23990662328656578, 0.11497260668394908, 0.013773860131903716])
    assert close(st.levy_stable.cdf(xs, 1.6, 0.4), [0.03477435255549932, 0.2816177948440568, 0.5005089770277258, 0.5562665392216002, 0.6596492944943806, 0.8534926749285345, 0.9697102796919914])
    assert close(st.levy_stable.pdf(xs, 1.6, 0.4, loc=0.5, scale=2.0), [0.07289146536641741, 0.13461443902202444, 0.14223438869059213, 0.14182561878854558, 0.13834347148120163, 0.11449561873452628, 0.046358044649268536])
    assert close(st.levy_stable.rvs(1.6, 0.4, size=5, random_state=np.random.RandomState(3)), [-0.03887513250872853, 0.3866679290134693, -0.7325356874637997, -0.07813709696084799, 1.730014855561543], 1e-9)

